int stringx::size() const { return data_[4]; }
void StringList::Break(void)
{
  int xLo = RANGE_BX_LO, xHi = RANGE_BX_HI;
  int yLo = RANGE_BY_LO, yHi = RANGE_BY_HI;
  int amt;

  adjustSizes(xLo, yLo);
  adjustSizes(xHi, yHi);

  for (int i = 0; i < data.size(); i++)
  {
    amt = random(xLo, xHi);
    if (random(2) == 1) amt = -amt;
    delta_x[i] += amt;

    amt = random(yLo, yHi);
    if (random(2) == 1) amt = -amt;
    delta_y[i] += amt;
  }
}
